import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a single sword → base premium 100 G");
    it.todo("a single amulet → base premium 60 G");
    it.todo("a single staff → base premium 80 G");
    it.todo("a single potion → base premium 40 G");
    it.todo("a single rune → base premium 25 G");
    it.todo("a single moonstone → base premium 25 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium (no block — block requires exactly 3)");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("a cursed sword → 100 G base + 50 G curse surcharge");
    it.todo("a sword with enchantment 5 → 100 G base + 30 G high-enchantment surcharge");
    it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("a cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30)");
    it.todo(
      "a cursed sword with enchantment 4 → only the curse surcharge applies (100 + 50)",
    );
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("every quote carries a 10 % first-insurance surcharge");
    it.todo("the second quote of a scenario gets a 15 % follow-up contract discount");
    it.todo("a 5 G processing fee is added to every premium");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo(
      "cursed sword (100 G) + plain amulet (60 G) → curse surcharge is 50 G (50 % of the cursed item only), policy base 210 G before further modifiers and fee",
    );
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  });

  describe("quote — integration examples", () => {
    it.todo(
      "newcomer (0 years, first contract) with a cursed steel sword (enchantment 3) → premium 165 G",
    );
    it.todo(
      "long-standing customer (3 years), second quote, cursed sword (enchantment 7) → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo(
      "regular sword (steel, enchantment 3), damage 500 G → payout 400 G (deductible only)",
    );
    it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo(
      "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)",
    );
    it.todo(
      "steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)",
    );
    it.todo(
      "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G",
    );
    it.todo(
      "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)",
    );
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "a dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible applies once per damaged item)",
    );
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — cap exhaustion", () => {
    it.todo(
      "a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G",
    );
    it.todo(
      "a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)",
    );
    it.todo(
      "a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (block discount affects the premium only)",
    );
    it.todo(
      "a sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G",
    );
    it.todo(
      "a sword policy (cap 2000 G), second successive claim of 1500 G → payout 600 G, remainingCap 0 G",
    );
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
    it.todo(
      "two sword damage entries against a policy with two swords → each entry gets its own deductible",
    );
    it.todo(
      "more damage entries of a type than the policy covers → the claim is rejected with an error",
    );
  });

  describe("errors", () => {
    it.todo("quote with an unknown item type (e.g. broomstick) → error");
    it.todo("claim referencing an item that is not part of the policy → error");
    it.todo("claim referencing a damaged item with an unknown type → error");
    it.todo("claim with a damage entry of amount -200 → error");
  });

  describe("CLI", () => {
    it.todo(
      "reads a scenario from stdin and writes {results: [...]} to stdout, one result per step in order",
    );
    it.todo("exits with a non-zero status code and writes to stderr on an invalid scenario");
    it.todo("writes no results to stdout when the scenario is invalid");
  });
});

