export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: { op: string; items: { type: string }[] }[];
};

export type ScenarioResult = {
  results: { premium: number }[];
};

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// Percentages stay in integer percent points: multiply first, divide by 100
// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
// a sword and breaks the ceil. `(base * 110) / 100` gives exactly 110.
const increasedBy = (amount: number, percent: number): number =>
  (amount * (100 + percent)) / 100;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: { type: string }[]): Map<string, number> => {
  const counts = new Map<string, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
};

const baseOfGroup = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBaseOf = (items: { type: string }[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + baseOfGroup(type, count),
    0,
  );

const withFirstInsuranceSurcharge = (policyBase: number): number =>
  increasedBy(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);

const quote = (items: { type: string }[]): number => {
  const surcharged = withFirstInsuranceSurcharge(policyBaseOf(items));

  // Rounding is in the MHPCO's favour: premiums round up.
  return Math.ceil(surcharged) + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
});

