// the progress the *next* step inherits. Dispatch on `step.op` lives here:
// a new op is a new branch, and the loop below is unaffected.
const runStep = (
  step: Step,
  customer: Customer,
  progress: ScenarioProgress,
): { result: StepResult; progress: ScenarioProgress } => ({
  result: {
    premium: quote(step.items, {
      customer,
      quoteOrdinal: progress.quotesSoFar,
    }),
  },
  progress: { quotesSoFar: progress.quotesSoFar + 1 },
});

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results: StepResult[] = [];
  let progress: ScenarioProgress = { quotesSoFar: 0 };

  for (const step of scenario.steps) {
    const stepRun = runStep(step, scenario.customer, progress);

    results.push(stepRun.result);
    progress = stepRun.progress;
  }

  return { results };
};

