// Takes the whole policy rather than the damage alone because the clauses
// grade the reimbursement by the *damaged item's* properties (enchantment,
// material), which only the policy can resolve from itemType.
// The damaged item is matched by type alone, so with two swords insured both
// sword damages resolve to the first. That is harmless while every item of a
// type is interchangeable for reimbursement purposes; the case that forces a
// positional match is rejecting more damage entries of a type than the policy
// covers, which needs a count rather than a lookup.
const reimbursableForDamage = (
  policy: IssuedPolicy,
  damage: Damage,
): number => {
  const damagedItem = policy.items.find(
    (item) => item.type === damage.itemType,
  );

  const reimbursement = damagedItem
    ? percentOf(damage.amount, reimbursementPercentFor(damagedItem))
    : damage.amount;

  return reimbursement - DEDUCTIBLE_PER_DAMAGE;
};

